// Framework configuration with icons and build settings
const FRAMEWORK_CONFIG = {
  angular: {
    id: 'angular',
    name: 'Angular',
    icon: AngularIcon,
    buildCommand: 'ng build',
    outputDirectory: './dist',
  },
  react: {
    id: 'react',
    name: 'React',
    icon: ReactIcon,
    buildCommand: 'npm run build',
    outputDirectory: './build',
  },
  vue: {
    id: 'vue',
    name: 'Vue',
    icon: VueIcon,
    buildCommand: 'npm run build',
    outputDirectory: './dist',
  },
  vite: {
    id: 'vite',
    name: 'Vite',
    icon: ViteIcon,
    buildCommand: 'npm run build',
    outputDirectory: './dist',
  },
  astro: {
    id: 'astro',
    name: 'Astro',
    icon: AstroIcon,
    buildCommand: 'npm run build',
    outputDirectory: './dist',
  },
} as const

const PACKAGE_MANAGER_CONFIG = {
  npm: {
    installCommand: 'npm ci',
  },
  yarn: {
    installCommand: 'yarn install --frozen-lockfile',
  },
  pnpm: {
    installCommand: 'pnpm install --frozen-lockfile',
  },
} as const

const WORKFLOW_NAME = 'Deploy to GitHub Pages'

function getDeploymentDefaults(
  packageManager: string | undefined,
  frameworkId: string | undefined,
): {
  install?: string
  build?: string
  output?: string
} {
  const packageManagerConfig = PACKAGE_MANAGER_CONFIG[packageManager as keyof typeof PACKAGE_MANAGER_CONFIG]

  const frameworkConfig =
    frameworkId && frameworkId in FRAMEWORK_CONFIG
      ? FRAMEWORK_CONFIG[frameworkId as keyof typeof FRAMEWORK_CONFIG]
      : undefined

  return {
    install: packageManagerConfig?.installCommand,
    build: frameworkConfig?.buildCommand,
    output: frameworkConfig?.outputDirectory,
  }
}

// Component to render framework option with icon and name
function FrameworkOption({framework}: {framework: (typeof FRAMEWORK_CONFIG)[keyof typeof FRAMEWORK_CONFIG]}) {
  const IconComponent = framework.icon
  return (
    <div className={styles.frameworkOption}>
      <IconComponent size={16} />
      {framework.name}
    </div>
  )
}

export function DeployForm() {
  const navigate = useNavigate()
  const {user_id, repository} = useRouteParams(deployFormRoute)
  const payload = useRouteQuery(deployFormRoute, 'mainQuery')
  const {workflowFilePath, webCommitInfo, branch, framework, packageManager} = payload.data
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const [selectedFrameworkId, setSelectedFrameworkId] = useState<keyof typeof FRAMEWORK_CONFIG>('vite')
  const selectedFramework = FRAMEWORK_CONFIG[selectedFrameworkId]
  const [isShowingBuildSettings, setShowBuildSettings] = useState(false)
  const [isShowingEnvVars, setShowEnvVariables] = useState(false)
  const [envVars, setEnvVars] = useState<Array<{k: string; value: string}>>([{k: '', value: ''}])

  const defaults = useMemo(
    () => getDeploymentDefaults(packageManager, selectedFrameworkId),
    [packageManager, selectedFrameworkId],
  )

  const [buildCommand, setBuildCommand] = useState(defaults.build || 'npm run build')
  const [outputDirectory, setOutputDirectory] = useState(defaults.output || './dist')
  const [installCommand, setInstallCommand] = useState(defaults.install || 'npm ci')

  useEffect(() => {
    setBuildCommand(defaults.build || 'npm run build')
    setOutputDirectory(defaults.output || './dist')
    setInstallCommand(defaults.install || 'npm ci')
  }, [defaults])

  useEffect(() => {
    if (framework && framework in FRAMEWORK_CONFIG) {
      setSelectedFrameworkId(framework as keyof typeof FRAMEWORK_CONFIG)
    }
  }, [framework])

  const addEnvVar = () => {
    setEnvVars(prev => [...prev, {k: '', value: ''}])
  }

  const removeEnvVar = (index: number) => {
    if (envVars.length > 1) {
      setEnvVars(prev => prev.filter((_, i) => i !== index))
    }
  }

  const updateEnvVar = (index: number, field: 'k' | 'value', value: string) => {
    setEnvVars(prev => prev.map((envVar, i) => (i === index ? {...envVar, [field]: value} : envVar)))
  }

  const handleDeploy = async () => {
    setIsSubmitting(true)
    setError(null)

    try {
      // Set the Pages build type to "workflow"
      await setPagesBuildTypeToWorkflow({
        owner: user_id,
        repo: repository,
      })

      // Create workflow file using state values directly
      await saveWorkflowFile({
        workflowFilePath,
        webCommitInfo,
        branch,
        installCommand,
        buildCommand,
        outputDirectory,
        envVars,
      })

      const workflowRun = await waitForNewRun({
        owner: user_id,
        repo: repository,
      })

      navigate(actionsWorkflowRunPath({owner: user_id, repo: repository, runId: `${workflowRun.id}`}))
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An unknown error occurred')
      setIsSubmitting(false)
    }
  }

  return (
    <PageLayout>
      <PageLayout.Content as="div" width="medium" className="m-3">
        <div className="mb-2 ml-6">
          <h3>Deploy with Pages</h3>
          <p className="color-fg-muted mt-1">
            Turn your GitHub repository into a shareable website using GitHub Pages.{' '}
            <Link href="https://docs.github.com/pages" target="_blank" inline>
              Learn more
            </Link>
          </p>
        </div>

        <Timeline clipSidebar>
          <Timeline.Item>
            <Timeline.Badge>
              <span className={styles.timelineNumber}>1</span>
            </Timeline.Badge>
            <Timeline.Body>
              <p className={styles.heading}>General</p>
              <div className="my-3">
                <p className="color-fg-default text-bold f5">Repository</p>
                <div className={styles.branchContainer}>
                  <span className={styles.branch}>
                    <GitHubAvatar src={`/${user_id}.png`} size={20} />
                    {user_id}/{repository} <BranchName>{branch}</BranchName>
                  </span>
                </div>
              </div>
              <FormControl>
                <FormControl.Label>Framework preset</FormControl.Label>
                <ActionMenu>
                  <ActionMenu.Button>
                    <FrameworkOption framework={selectedFramework} />
                  </ActionMenu.Button>
                  <ActionMenu.Overlay>
                    <ActionList selectionVariant="single">
                      {Object.values(FRAMEWORK_CONFIG).map(frameworkOption => (
                        <ActionList.Item
                          key={frameworkOption.id}
                          selected={selectedFramework.id === frameworkOption.id}
                          onSelect={() => setSelectedFrameworkId(frameworkOption.id)}
                        >
                          <FrameworkOption framework={frameworkOption} />
                        </ActionList.Item>
                      ))}
                    </ActionList>
                  </ActionMenu.Overlay>
                </ActionMenu>
              </FormControl>
            </Timeline.Body>
          </Timeline.Item>
          <Timeline.Item>
            <Timeline.Badge>
              <span className={styles.timelineNumber}>2</span>
            </Timeline.Badge>
            <Timeline.Body>
              <p className={styles.heading}>Configuration</p>
              <div className={styles.configContainer}>
                <div className="border-bottom">
                  <button
                    className={styles.accordionTrigger}
                    onClick={() => setShowBuildSettings(!isShowingBuildSettings)}
                    aria-expanded={isShowingBuildSettings}
                    aria-controls="build-settings-content"
                  >
                    <div className={styles.accordionLabel}>
                      <ChevronRightIcon className={styles.chevron} data-expanded={isShowingBuildSettings} />
                      Build and output settings
                    </div>
                  </button>
                  {isShowingBuildSettings && (
                    <Stack className="px-3 pt-2 pb-5" id="build-settings-content">
                      <FormControl>
                        <FormControl.Label>Build command</FormControl.Label>
                        <TextInput
                          name="build"
                          value={buildCommand}
                          onChange={e => setBuildCommand(e.target.value)}
                          placeholder="Example: npm run build"
                          block
                          monospace
                        />
                      </FormControl>
                      <FormControl>
                        <FormControl.Label>Output directory</FormControl.Label>
                        <TextInput
                          name="output"
                          value={outputDirectory}
                          onChange={e => setOutputDirectory(e.target.value)}
                          placeholder="Example: dist"
                          block
                          monospace
                        />
                      </FormControl>
                      <FormControl>
                        <FormControl.Label>Install command</FormControl.Label>
                        <TextInput
                          name="install"
                          value={installCommand}
                          onChange={e => setInstallCommand(e.target.value)}
                          placeholder="Example: npm install"
                          block
                          monospace
                        />
                      </FormControl>
                    </Stack>
                  )}
                </div>
                <button
                  className={styles.accordionTrigger}
                  onClick={() => setShowEnvVariables(!isShowingEnvVars)}
                  aria-expanded={isShowingEnvVars}
                  aria-controls="env-variables-content"
                >
                  <div className={styles.accordionLabel}>
                    <ChevronRightIcon className={styles.chevron} data-expanded={isShowingEnvVars} />
                    Environment variables
                  </div>
                </button>
                {isShowingEnvVars && (
                  <div className={styles.envVarsContent} id="env-variables-content">
                    <div className={styles.envVars}>
                      <span className="f6">Key</span>
                      <span className="f6">Value</span>
                      <span />
                      {envVars.map((envVar, i) => (
                        // eslint-disable-next-line @eslint-react/no-array-index-key
                        <Fragment key={i}>
                          <TextInput
                            value={envVar.k}
                            onChange={e => updateEnvVar(i, 'k', e.target.value)}
                            placeholder="YOUR_KEY"
                            monospace
                          />
                          <TextInput
                            value={envVar.value}
                            onChange={e => updateEnvVar(i, 'value', e.target.value)}
                            placeholder="GHSECRET2008C0DE"
                            monospace
                          />
                          <IconButton
                            variant="invisible"
                            icon={XIcon}
                            onClick={() => removeEnvVar(i)}
                            aria-label="Delete variable"
                          />
                        </Fragment>
                      ))}
                    </div>
                    <Button variant="default" onClick={addEnvVar}>
                      Add variable
                    </Button>
                  </div>
                )}
              </div>
            </Timeline.Body>
          </Timeline.Item>
          <Timeline.Item>
            <Timeline.Badge>
              <span className={styles.timelineNumber}>3</span>
            </Timeline.Badge>
            <Timeline.Body>
              <p className={styles.heading}>Deployment</p>
              <>
                <p>Once you&apos;re ready, start deploying to see the progress...</p>
                {error ? (
                  <Banner variant="critical" title="Error" description={error} onDismiss={() => setError(null)} />
                ) : null}
                <Button variant="primary" loading={isSubmitting} className="mt-3" onClick={handleDeploy}>
                  Deploy
                </Button>
              </>
            </Timeline.Body>
          </Timeline.Item>
        </Timeline>
      </PageLayout.Content>
    </PageLayout>
  )
}

async function setPagesBuildTypeToWorkflow({owner, repo}: {owner: string; repo: string}) {
  const formData = new FormData()
  formData.set('build_type', 'workflow')

  const response = await reactFetch(`/${owner}/${repo}/settings/pages/build_type`, {
    method: 'PUT',
    body: formData,
    headers: {
      Accept: 'application/json',
    },
  })

  if (!response.ok) {
    // Try to get error message from response
    try {
      const errorData = await response.json()
      throw new Error(errorData.error || `Failed to set Pages build type to workflow (${response.status})`)
    } catch {
      throw new Error(`Failed to set Pages build type to workflow (${response.status})`)
    }
  }
}

const waitForNewRun = async ({
  owner,
  repo,
  interval = 1000,
  timeout = 60000,
}: {
  owner: string
  repo: string
  interval?: number
  timeout?: number
}) => {
  const endpoint = `/${owner}/${repo}/deploy/runs`
  const start = Date.now()
  let lastSeenId = 0
  const firstResp = await verifiedFetchJSON(endpoint, {
    headers: {Accept: 'application/json'},
  })

  if (firstResp.ok) {
    const firstData = await firstResp.json()
    if (Array.isArray(firstData.workflow_runs)) {
      lastSeenId = firstData.workflow_runs[0]?.id ?? 0
    } else {
      throw new Error("Invalid API response: 'workflow_runs' is not an array")
    }
  }

  while (Date.now() - start < timeout) {
    await new Promise(r => setTimeout(r, interval))

    const resp = await verifiedFetchJSON(endpoint, {
      headers: {Accept: 'application/json'},
    })
    if (!resp.ok) {
      // we might receive a 404 if the workflow file doesn't exist yet, so we just:
      continue
    }

    const data = await resp.json()

    if (Array.isArray(data.workflow_runs) && data.workflow_runs[0]?.id > lastSeenId) {
      return data.workflow_runs[0]
    }
  }

  throw new Error(
    `Failed to retrieve new workflow run within ${
      timeout / 1000
    }s. The deployment may still be processing - check the Actions tab for updates.`,
  )
}

interface ISaveBlobData {
  message: string
  placeholder_message: string
  description: string
  author_email?: string
  'commit-choice'?: string
  target_branch?: string
  quick_pull: string
  guidance_task: string
  commit: string
  same_repo?: number
  pr: string
}

interface IEditSaveBlobData extends ISaveBlobData {
  content_changed: boolean
  filename: string
  new_filename: string
  value: string
}

async function saveWorkflowFile({
  workflowFilePath: workflowFilePathParam,
  webCommitInfo,
  branch,
  installCommand,
  buildCommand,
  outputDirectory,
  envVars,
}: {
  workflowFilePath: string
  webCommitInfo: WebCommitInfo
  branch: string
  installCommand: string
  buildCommand: string
  outputDirectory: string
  envVars: Array<{k: string; value: string}>
}) {
  // TODO: Handle empty repo and fork
  const data: IEditSaveBlobData = {
    message: WORKFLOW_NAME,
    placeholder_message: 'Deploy to GitHub Pages',
    description: 'Configure automatic deployment to GitHub Pages using GitHub Actions',
    quick_pull: '',
    guidance_task: '',
    commit: webCommitInfo.commitOid,
    pr: '',
    content_changed: true,
    filename: workflowFilePathParam,
    new_filename: workflowFilePathParam,
    same_repo: 1,
    value: workflowTemplate({
      branch,
      installCommand,
      buildCommand,
      outputDirectory,
      envVars,
    }),
  }

  const formData = new FormData()
  for (const [key, value] of Object.entries(data)) {
    if (value !== undefined) {
      formData.set(key, value)
    }
  }

  const response = await reactFetch(webCommitInfo.saveUrl, {
    method: 'post',
    body: formData,
    headers: {
      Accept: 'application/json',
    },
  })

  if (!response.ok) {
    // Try to get error message from response
    try {
      const errorData = await response.json()
      throw new Error(errorData.data.error || `Failed to save workflow file (${response.status})`)
    } catch {
      throw new Error(`Failed to save workflow file (${response.status})`)
    }
  }
}

function workflowTemplate({
  branch,
  installCommand,
  buildCommand,
  outputDirectory,
  envVars,
}: {
  branch: string
  installCommand: string
  buildCommand: string
  outputDirectory: string
  envVars: Array<{k: string; value: string}>
}) {
  const installStep = installCommand
    ? `
      - name: Install dependencies
        run: ${installCommand}`
    : ''

  const buildStep = buildCommand
    ? `
      - name: Build
        run: ${buildCommand}`
    : ''

  // Generate top-level environment variables section if any non-empty env vars exist
  const validEnvVars = envVars.filter(envVar => envVar.k.trim() && envVar.value.trim())
  const envSection =
    validEnvVars.length > 0
      ? `

# Environment variables
env:${validEnvVars
          .map(
            envVar => `
  ${envVar.k}: "${envVar.value}"`,
          )
          .join('')}`
      : ''

  return `# Workflow for building and deploying to GitHub Pages
name: ${WORKFLOW_NAME}

on:
  # Runs on pushes targeting the default branch
  push:
    branches: ["${branch}"]

  # Allows you to run this workflow manually from the Actions tab
  workflow_dispatch:
${envSection}

# Sets permissions of the GITHUB_TOKEN to allow deployment to GitHub Pages
permissions:
  contents: read
  pages: write
  id-token: write

# Allow only one concurrent deployment, skipping runs queued between the run in-progress and latest queued.
# However, do NOT cancel in-progress runs as we want to allow these production deployments to complete.
concurrency:
  group: "pages"
  cancel-in-progress: false

jobs:
  # Build job
  build:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout
        uses: actions/checkout@v4
      - name: Setup Node
        uses: actions/setup-node@v4
        with:
          node-version: "20"
      - name: Setup Pages
        uses: actions/configure-pages@v5${installStep}${buildStep}
      - name: Upload artifact
        uses: actions/upload-pages-artifact@v3
        with:
          path: ${outputDirectory || '.'}

  # Deployment job
  deploy:
    environment:
      name: github-pages
      url: \${{ steps.deployment.outputs.page_url }}
    runs-on: ubuntu-latest
    needs: build
    steps:
      - name: ${WORKFLOW_NAME}
        id: deployment
        uses: actions/deploy-pages@v4`
}

try{ FrameworkOption.displayName ||= 'FrameworkOption' } catch {}
